cases.text:
capa {
  titulo "Catálogo de layouts da SlideDSL Alto"
  subtitulo "Onze tipos de slide; o compilador calcula geometria, tipografia e cores"
  autor "Conteúdo ilustrativo"
}

secao {
  titulo "Estruturas de texto"
  subtitulo "Tópicos, etapas e conclusões"
}

topicos {
  titulo "Até três tópicos alternam entre lista e cards"
  item "Mensagem" "O título afirma a ideia que o slide precisa provar ao público."
  item "Evidência" "Cada card traz um fato, número ou exemplo verificável com fonte."
  item "Ressalva" "Quando a conclusão depende de contexto, a condição aparece aqui."
}

citacao {
  texto "A simplicidade é o último grau de sofisticação."
  autor "Frase popularmente atribuída a Leonardo da Vinci"
}

capa {
  titulo "Monolito ou microsserviços: quando cada um compensa"
  subtitulo "O que Netflix, Amazon e Prime Video aprenderam ao dividir (e reunir) sistemas"
  autor "SlideDSL Alto — exemplo"
}

comparacao {
  titulo "A diferença está em como o sistema é implantado e escalado"
  lado "Monolito" {
    item "Uma unidade de implantação" "Toda mudança exige recompilar e publicar a aplicação inteira."
    item "Escala em bloco" "Para atender um módulo sobrecarregado, replica-se o sistema todo."
    item "Chamadas em memória" "Módulos conversam por funções, sem latência de rede."
  }
  lado "Microsserviços" {
    item "Serviços independentes" "Cada serviço tem implantação, dados e equipe próprios."
    item "Escala por serviço" "Só o serviço sob carga recebe mais instâncias."
    item "Chamadas pela rede" "Cada interação passa por HTTP ou filas e pode falhar."
  }
  fontes "Lewis & Fowler, Microservices (martinfowler.com, 2014)"
}

numeros {
  titulo "Os resultados dependem do problema, não da moda"
  valor "7 anos" "duração da migração da Netflix para a nuvem, de 2008 a 2016"
  valor "90%" "redução de custo de infraestrutura no monitoramento do Prime Video ao abandonar a versão distribuída"
  fontes "Netflix Tech Blog (2016)", "Prime Video Tech Blog (2023)"
}

conclusao {
  titulo "Comece simples e divida quando a dor for real"
  item "Monolito modular primeiro" "Fronteiras claras dentro de um processo custam pouco e facilitam a divisão futura."
  item "Divida por escala ou equipe" "Microsserviços compensam quando partes escalam ou evoluem em ritmos diferentes."
  item "Meça antes e depois" "Custos de rede, observabilidade e operação devem entrar na decisão."
}

capa {
  titulo "Quando microsserviços compensam"
  subtitulo "Casos reais"
}

topicos {
  titulo "Três sinais de que vale dividir"
  item "Escala desigual" "Na Black Friday só o serviço de pagamentos precisa de dez vezes mais réplicas."
  item "Equipes independentes" "Times da Amazon publicam serviços sem coordenar implantações entre si."
  notas "Cada sinal vem com um exemplo concreto do mercado."
}

conclusao {
  titulo "Divida quando a dor for real"
  item "Comece modular" "Fronteiras claras dentro de um único processo custam pouco e ajudam depois."
  item "Meça o custo" "Some rede, observabilidade e plantão antes de criar um novo serviço."
}

numeros {
  titulo "Voltar ao monolito cortou 90% do custo"
  valor "90%" "redução de custo no Prime Video"
  fontes F1
}

capa {
  titulo "Projetos pequenos precisam de foco"
  subtitulo "Comece pelo problema e delimite o resultado esperado."
  notas "Explique as condições."
}

topicos {
  titulo "Projetos pequenos precisam de foco"
  item "Definir escopo" "A equipe reduz retrabalho quando define o resultado antes de começar."
  item "Revisar entregas" "A equipe verifica cada entrega e corrige problemas antes de seguir."
  notas "Explique as condições."
}

conclusao {
  titulo "Projetos pequenos precisam de foco"
  item "Documentar decisões" "Registre as escolhas para orientar quem entrar depois no projeto."
  item "Planejar a continuidade" "Escolha a próxima atividade com base no resultado da entrega atual."
  notas "Explique as condições."
}

capa {
  titulo "SlideDSL"
}

topicos {
  titulo "O compilador organiza a apresentação"
  item "Linguagem formal" "A gramática limita as estruturas aceitas pelo sistema."
  item "Cena explícita" "O compilador organiza os objetos antes da exportação."
}

conclusao {
  titulo "Revise a apresentação antes da defesa"
  item "Conferir as fontes" "Leia os trechos usados antes de apresentar os resultados."
  item "Abrir o PowerPoint" "Revise os objetos editáveis no programa de apresentação."
}

comparacao {
  titulo "Monolito e microsserviços têm trade-offs"
  lado "Monolito" {
    item "Simplicidade inicial" "Arquitetura única facilita o desenvolvimento e implantação no começo."
    item "Menor custo operacional" "Requer menos infraestrutura e menos ferramentas para gerenciar o sistema."
  }
  lado "Microsserviços" {
    item "Escalabilidade modular" "Permite escalar partes específicas do sistema conforme a necessidade."
    item "Complexidade maior" "Exige orquestração e monitoramento de múltiplos serviços independentes."
  }
  notas "Este slide compara os principais pontos fortes e fracos do monolito e dos microsserviços, ajudando a entender os trade-offs para a decisão arquitetural."
}

comparacao {
  titulo "Microsserviços compensam quando a dor é real"
  lado "Monolito" {
    item "Fluxo ainda acoplado" "O pedido do cliente atravessa cadastro, pagamento e entrega no mesmo caminho."
    item "Equipe pequena" "Poucas pessoas conseguem revisar e publicar o sistema inteiro sem fila longa."
  }
  lado "Microsserviços" {
    item "Domínios separados" "Cada serviço responde por uma parte clara, como cobrança ou catálogo."
    item "Escala diferente" "Uma área recebe mais tráfego e precisa crescer sem levar o resto junto."
  }
  notas "A comparação mostra que a separação vale quando o produto já tem fronteiras de domínio nítidas ou necessidades de escala distintas. Antes disso, o custo de dividir pode superar o benefício. O ponto central é evitar fragmentar um fluxo que ainda funciona melhor unido."
}

secao {
  titulo "Na escola, o sinal precisa ficar claro"
  subtitulo "A turma separa melhor quando encontra orientação visível no ponto de descarte."
  notas "A mudança principal é reduzir dúvida no momento do descarte. Pense em sinalização simples, linguagem direta e localização fácil. O objetivo é fazer a escolha certa sem depender da memória de cada aluno."
}

comparacao {
  titulo "Monolito tem menos complexidade, microsserviços mais flexíveis"
  lado "Monolito" {
    item "Complexidade reduzida" "Arquitetura única simplifica o desenvolvimento e a implantação inicial."
    item "Gerenciamento centralizado" "Todas as funcionalidades estão em um único código e ambiente."
  }
  lado "Microsserviços" {
    item "Flexibilidade para equipes" "Times podem trabalhar em serviços independentes com tecnologias distintas."
    item "Resiliência aprimorada" "Falhas em um serviço não comprometem todo o sistema."
  }
  notas "Este slide compara os dois modelos destacando que monolitos são mais simples, enquanto microsserviços oferecem maior flexibilidade e resiliência."
}

comparacao {
  titulo "O custo oculto muda a decisão"
  lado "Monolito" {
    item "Operação mais simples" "Um único deploy concentra monitoramento, logs e rollback em um ponto só."
    item "Coordenação menor" "Uma equipe compartilha o mesmo código e reduz alinhamentos entre serviços."
  }
  lado "Microsserviços" {
    item "Operação distribuída" "Vários serviços exigem observabilidade, rede e falhas em conjunto."
    item "Coordenação maior" "Mais equipes precisam combinar contratos, versões e mudanças com frequência."
  }
  notas "Compare o custo invisível, não só a flexibilidade prometida. O monolito simplifica operação e comunicação; microsserviços aumentam a autonomia, mas cobram disciplina de integração. A decisão depende de qual custo a startup consegue absorver agora."
}

capa {
  titulo "Energia Solar Residencial: Entenda Antes de Avaliar"
  subtitulo "Conheça como a energia solar pode transformar sua casa e saiba o que considerar antes de instalar"
  notas "Este slide de abertura apresenta o tema da apresentação, focando em despertar o interesse do público leigo para entender a energia solar residencial. A promessa é mostrar os conceitos básicos e os cuidados necessários antes de solicitar uma avaliação profissional, preparando o espectador para os próximos slides."
}

comparacao {
  titulo "Telhado e luz disponível influenciam o aproveitamento"
  lado "Telhado" {
    item "Posição do telhado" "Telhados voltados para o sul recebem mais luz disponível durante o dia."
    item "Inclinação do telhado" "Telhados inclinados otimizam a captação da luz disponível para os painéis."
    item "Sombreamento no telhado" "Árvores ou construções próximas podem reduzir a luz disponível no telhado."
  }
  lado "Cuidados na avaliação" {
    item "Avaliação do imóvel" "Verificar o estado do telhado garante a instalação segura dos painéis."
    item "Análise da luz disponível" "Avaliar obstáculos que limitam a luz disponível é essencial para o sistema."
    item "Cuidados na avaliação" "Profissionais avaliam telhado e luz disponível para dimensionar o sistema."
  }
  notas "Este slide compara aspectos do telhado e da luz disponível que afetam a eficiência dos painéis solares. A posição, inclinação e sombreamento do telhado influenciam diretamente a captação de luz. Na avaliação do imóvel, é essencial verificar o estado do telhado e possíveis obstáculos que limitam a luz disponível. Ressalte que uma avaliação profissional é fundamental para garantir o melhor aproveitamento do sistema solar."
}

capa {
  titulo "Energia Solar Residencial: Entenda Antes de Avaliar"
  subtitulo "Conheça os conceitos básicos para decidir com segurança sobre energia solar em sua casa"
  notas "Este slide de abertura apresenta o tema principal da apresentação, focando em moradores leigos que desejam entender a tecnologia antes de buscar uma avaliação profissional. A promessa é oferecer uma base clara e acessível para que possam tomar decisões informadas. É importante destacar que o conteúdo será didático e sem termos técnicos complexos."
}

capa {
  titulo "Fotossíntese: a energia que move as plantas"
  subtitulo "Abertura para entender como as plantas transformam luz em vida e energia"
  notas "Este slide serve para introduzir o tema da fotossíntese de forma simples e instigante, preparando os estudantes para os conceitos que virão nos próximos slides. A ideia é despertar a curiosidade sobre como as plantas usam a luz do sol para produzir energia, um processo fundamental para a vida na Terra. Ressalte que a apresentação vai explicar passo a passo esse fenômeno natural."
}

comparacao {
  titulo "Luz, água e CO₂ viram açúcar e oxigênio"
  lado "Entradas da fotossíntese" {
    item "Luz solar capturada" "As folhas capturam luz solar para fornecer energia ao processo químico."
    item "Água absorvida" "As raízes absorvem água do solo para ser usada na produção de açúcares."
    item "Gás carbônico" "As folhas absorvem gás carbônico do ar para formar moléculas de açúcar."
  }
  lado "Saídas da fotossíntese" {
    item "Açúcares produzidos" "As plantas produzem açúcares que alimentam e energizam seu crescimento."
    item "Oxigênio liberado" "As folhas liberam oxigênio no ar, essencial para a respiração dos seres vivos."
  }
  notas "Este slide compara as entradas e saídas da fotossíntese para facilitar a compreensão dos estudantes. As entradas são luz, água e gás carbônico, que as plantas captam para produzir açúcares. As saídas são os açúcares, usados como energia, e o oxigênio, liberado para o ambiente. É importante destacar que a luz é capturada pelas folhas, a água vem das raízes e o gás carbônico do ar, enquanto o oxigênio sai pelas folhas."
}

capa {
  titulo "Fotossíntese: energia e vida das plantas"
  subtitulo "Abertura para entender como as plantas transformam luz em alimento e oxigênio"
  notas "Este slide serve para introduzir o tema da fotossíntese, destacando sua importância para a vida das plantas e para o ambiente. A ideia é despertar a curiosidade dos estudantes sobre como a luz solar é usada pelas plantas para produzir energia e sustentar a vida. Ressalte que esta é uma introdução para facilitar o aprendizado dos próximos slides."
}

capa {
  titulo "Comece a usar Git para controlar seus trabalhos"
  subtitulo "Aprenda a gerenciar versões e evitar perdas com um sistema eficiente e simples"
  notas "Este slide de abertura apresenta o tema da apresentação, destacando a promessa de facilitar o controle de versões dos trabalhos acadêmicos. O objetivo é motivar os calouros a entenderem que o Git pode substituir as cópias manuais, trazendo organização e segurança."
}

capa {
  titulo "Controle seu código com Git desde o início"
  subtitulo "Aprenda a gerenciar versões e evitar perdas com um sistema simples e eficiente"
  notas "Este slide de abertura apresenta o tema principal da apresentação, destacando a importância do Git para o controle de versões desde os primeiros projetos. A promessa é mostrar como o Git ajuda a evitar perdas e confusões comuns ao salvar cópias manuais. É importante motivar os calouros a adotarem essa ferramenta desde o começo para facilitar seu aprendizado e organização."
}

capa {
  titulo "Energia solar residencial descomplicada"
  subtitulo "Entenda como a luz do sol vira eletricidade na sua casa de forma simples e prática"
  notas "Este slide de abertura deve captar a atenção do público leigo, mostrando que o tema será explicado de forma clara e acessível. O objetivo é motivar o interesse para que os moradores entendam o básico antes de buscar uma avaliação profissional. Evite termos técnicos neste momento para não assustar."
}

capa {
  titulo "Energia Solar Residencial Descomplicada"
  subtitulo "Entenda a conversão luz-eletricidade, a função dos painéis e do inversor, e como telhado e luz disponível influenciam o aproveitamento"
  notas "Este slide de abertura apresenta os conceitos básicos que serão abordados na apresentação para despertar o interesse do público leigo. A ideia é mostrar que a energia solar residencial envolve a conversão da luz em eletricidade, destacando a função dos painéis solares e do inversor, além da importância do telhado e da luz disponível para o desempenho do sistema. É importante preparar o público para os próximos slides, que detalharão cada um desses aspectos."
}

capa {
  titulo "Como as plantas produzem seu alimento"
  subtitulo "Abertura para entender a fotossíntese: luz, água e ar transformados em energia"
  notas "Este slide serve para introduzir o tema da fotossíntese aos estudantes do ensino médio, explicando que a apresentação mostrará como as plantas usam luz, água e gás carbônico para produzir seu alimento. É importante destacar que esta é uma abertura para despertar o interesse e preparar para os conceitos seguintes."
}

comparacao {
  titulo "Planta em sombra versus planta iluminada"
  lado "Planta em sombra" {
    item "Crescimento reduzido" "Plantas em sombra crescem menos devido à menor energia disponível."
    item "Menor produção de açúcar" "A fotossíntese é limitada pela pouca luz, reduzindo a produção de açúcar."
    item "Folhas maiores" "Plantas sombreadas têm folhas maiores para captar mais luz."
  }
  lado "Planta iluminada" {
    item "Crescimento acelerado" "Plantas sob luz intensa crescem mais rápido com energia abundante."
    item "Alta produção de açúcar" "A luz forte aumenta a fotossíntese e a produção de açúcar."
    item "Folhas menores" "Plantas iluminadas possuem folhas menores, pois a luz é suficiente."
  }
  notas "Este slide compara plantas em ambientes com diferentes níveis de luz para mostrar como a fotossíntese varia no cotidiano. Plantas em sombra adaptam-se com folhas maiores, mas crescem menos por falta de energia. Já plantas iluminadas produzem mais açúcar e crescem mais rápido, com folhas menores. Essa comparação ajuda a entender a importância da luz para o processo."
}

capa {
  titulo "Fotossíntese: energia e vida das plantas"
  subtitulo "Abertura para introdução da fotossíntese a estudantes do ensino médio"
  notas "Este slide serve para apresentar o tema da fotossíntese de forma clara e atrativa para estudantes que ainda não conhecem o processo. A ideia é preparar o público para entender como as plantas transformam luz, água e gás carbônico em energia e oxigênio. A abertura deve despertar interesse e mostrar a importância da fotossíntese para a vida na Terra."
}

topicos {
  titulo "Entradas e saídas da fotossíntese"
  item "Entradas essenciais" "A planta usa luz solar, água do solo e gás carbônico do ar para iniciar a fotossíntese."
  item "Saídas do processo" "A fotossíntese libera oxigênio para o ar e produz açúcar para a planta crescer."
  notas "Este slide destaca os elementos que entram e saem da fotossíntese, facilitando a compreensão do ciclo básico. A imagem deve ilustrar o processo para reforçar visualmente o conceito. É importante lembrar que a luz é captada pelas folhas, a água vem das raízes e o gás carbônico entra pelos estômatos."
}

capa {
  titulo "Comece a usar Git hoje"
  subtitulo "Orientação início para dominar o controle de versões e organizar seu código"
  notas "Este slide de abertura apresenta o tema da apresentação e destaca a promessa de orientar os calouros a começar a usar Git. A ideia é motivar o público mostrando que aprender Git é acessível e traz organização ao trabalho. Ressalte que a apresentação vai guiar passo a passo para facilitar o início."
}

capa {
  titulo "Comece a usar Git hoje"
  subtitulo "Aprenda a substituir cópias manuais por um controle de versões eficiente e organizado"
  notas "Este slide de abertura apresenta o tema central da apresentação, que é incentivar o uso do Git para evitar o problema comum de salvar várias cópias manuais de arquivos. A promessa é mostrar como o Git pode tornar o trabalho mais organizado e seguro para calouros que ainda não usam controle de versões."
}

topicos {
  titulo "Repositório e commits organizam o histórico"
  item "Histórico local" "O histórico local mostra todas as versões salvas no repositório do computador."
  item "Papel do repositório" "O repositório armazena arquivos e registra cada commit para organizar o histórico."
  notas "Este slide mostra como o repositório funciona como um banco de dados local que guarda o histórico de todas as versões do projeto. Os commits são pontos de controle que registram mudanças específicas, facilitando o acompanhamento da evolução do trabalho. A imagem ajuda a visualizar o conceito de repositório e commits como elementos centrais para organizar o histórico local."
}

capa {
  titulo "Internet para crianças: história e funcionamento"
  subtitulo "Descubra como a internet conecta o mundo e como usá-la com segurança no dia a dia"
  notas "Este slide de capa apresenta o tema da apresentação de forma clara e atrativa para crianças do ensino fundamental. O subtítulo promete uma descoberta sobre a internet, destacando a conexão global e a importância do uso seguro, o que ajuda a despertar o interesse dos alunos para os próximos slides."
}

comparacao {
  titulo "Internet conecta dispositivos; web é conteúdo"
  lado "Funcionamento da internet" {
    item "Rede de dispositivos" "A internet conecta computadores, celulares e outros aparelhos entre si."
    item "Troca de informações" "Dispositivos trocam dados para permitir comunicação e acesso a serviços."
  }
  lado "Diferença internet e web" {
    item "Internet como infraestrutura" "A internet é a rede que conecta dispositivos para comunicação entre eles."
    item "Web como conteúdo" "A web é o conjunto de sites e páginas acessados usando a internet."
  }
  notas "Este slide explica que a internet é a rede física e lógica que conecta dispositivos, enquanto a Web é o conteúdo acessado por meio dessa rede. É importante destacar que a internet permite várias funções além da Web, como mensagens e jogos online. Para crianças, usar exemplos simples como computadores e celulares ajuda a entender a diferença entre a infraestrutura (internet) e o conteúdo (Web)."
}

capa {
  titulo "História da internet para crianças"
  subtitulo "Vamos aprender a origem da Internet e como ela conecta o mundo de forma simples e divertida"
  notas "Este slide serve para introduzir o tema da Internet de forma acessível para crianças do ensino fundamental. A ideia é despertar a curiosidade sobre a história da Internet, mostrando que ela tem uma origem e uma evolução, e que é uma ferramenta que conecta pessoas e dispositivos. É importante usar uma linguagem simples e exemplos próximos do cotidiano delas para facilitar o entendimento."
}

conclusao {
  titulo "Conclusão e próximos passos para energia solar"
  item "Solicite avaliação técnica" "Contrate profissional para analisar seu imóvel e indicar a melhor solução solar."
  item "Pesquise fornecedores locais" "Consulte empresas especializadas para obter orçamentos e entender opções de instalação."
  notas "Este slide finaliza a apresentação destacando a importância de buscar ajuda profissional para garantir uma instalação adequada e eficiente. Recomendo que o público procure técnicos qualificados para avaliar as condições específicas do imóvel, pois cada casa tem características únicas que influenciam a viabilidade do sistema solar. Além disso, pesquisar fornecedores locais ajuda a comparar preços e serviços, facilitando uma decisão informada e segura."
}

topicos {
  titulo "Telhado e luz disponível afetam eficiência"
  item "Orientação do telhado" "Telhados voltados para o norte captam mais luz no hemisfério sul."
  item "Sombreamento local" "Árvores e prédios próximos reduzem a luz disponível no telhado."
  notas "Este slide mostra como a posição e o entorno do telhado afetam a captação de luz solar, essencial para o sistema funcionar bem. A orientação norte é preferida no Brasil para maior exposição solar, mas sombras de árvores ou prédios próximos podem diminuir a eficiência. É importante avaliar o telhado e seu entorno para garantir boa luz disponível antes da instalação."
}

conclusao {
  titulo "Conclusão e próximos passos para energia solar"
  item "Solicite avaliação técnica especializada" "Contrate um profissional para analisar as condições do seu imóvel e recomendar o sistema ideal."
  item "Planeje a instalação com base na avaliação" "Use o laudo técnico para definir o melhor momento e forma de instalar o sistema solar em sua casa."
  notas "Este slide finaliza a apresentação destacando a importância de buscar uma avaliação técnica especializada para garantir que o sistema solar seja adequado ao imóvel. Em seguida, recomenda planejar a instalação com base nessa avaliação para evitar problemas futuros e otimizar o aproveitamento da energia. Ressalte que esses passos são essenciais para uma decisão segura e eficiente na adoção da energia solar residencial."
}

topicos {
  titulo "Relação telhado e luz disponível"
  item "Orientação do telhado" "Telhados voltados para o norte recebem mais luz solar no hemisfério sul."
  item "Sombreamento local" "Árvores e prédios próximos podem reduzir a luz disponível para os painéis."
  notas "Este slide destaca como a posição e o entorno do telhado influenciam a quantidade de luz solar que os painéis recebem, afetando diretamente a eficiência do sistema. A orientação norte é preferida no Brasil para captar mais sol, mas sombras de árvores ou construções próximas podem diminuir essa captação. É importante avaliar esses fatores antes da instalação para garantir melhor aproveitamento da energia solar."
}

conclusao {
  titulo "Conclusão e próximos passos para instalar"
